// @ts-ignore - index.js is generated by napi-rs at build time; may not exist during type-check
import * as native from './index.js'

export interface ServeOptions {
  port: number
  workers: number
  entry: string
  bootTimeoutMs?: number
}

export type RenderFn = (path: string) => Promise<string>

// native.isWorker is a napi fn (not a getter); call once at module load —
// the env var BRUST_WORKER_ID is stable for the module's lifetime.
export const isWorker: boolean = (native as any).isWorker()

// native.workerId() reads a thread-local set by registerRenderer, so it must
// be re-evaluated at the point of use (not cached at module load).
export function workerId(): number | null {
  return (native as any).workerId()
}

export const brust = {
  async serve(opts: ServeOptions): Promise<void> {
    ;(native as any).beginServe({
      port: opts.port,
      workers: opts.workers,
      entry: opts.entry,
    })
    for (let i = 0; i < opts.workers; i++) {
      // Bun.Worker requires the JS entry (post-bundling). For the skeleton,
      // app/index.ts is a TS file that Bun executes directly.
      new Worker(opts.entry, {
        // @ts-expect-error - Bun supports `env` per Worker; types may lag
        env: { ...process.env, BRUST_WORKER_ID: String(i) },
      })
    }
    await (native as any).untilReady(opts.bootTimeoutMs ?? 5000)
    await (native as any).untilShutdown()
  },
  registerRenderer(fn: RenderFn): number {
    return (native as any).registerRenderer(fn)
  },
}
